const INDICE = (() => {
  const t = v => (v == null ? '' : String(v).replace(/\s+/g, ' ').trim());

  // Código de documento (#ST00=M00MKF10UZ010-UZ901&MPA010) e RDS-PP em geral (com ou sem &tipo).
  const RE_DOC = /#?ST\d{2}=[A-Z]\d{2}[A-Z]{3}\d{2}(?:[A-Z]{2}\d{3}(?:-[A-Z]{2}\d{3})?)?&[A-Z]{3}\d{3}/g;
