      for (let L = 2; L <= 4; L++) if (/^[A-Z]+$/.test(s.slice(i, i + L)) && i + L <= n) passa(i + L, 100 + L, null);
    }
    if (custo[n] === Infinity) return [];
    const tags = [];
    for (let j = n; j > 0; j = de[j][0]) if (de[j][1]) tags.unshift(de[j][1]);
