// ───────────────────────── 1. Constantes ─────────────────────────

// Ordem física das UGs: U-09A é a 10ª, U-10 a 11ª, U-18A a 20ª.
const UGS = [
  ...[1, 2, 3, 4, 5, 6, 7, 8, 9].map((n, i) => ({ pos: i + 1, trecho: `U-${pad2(n)}`, m: `M${pad2(n)}`, hz: 50 })),
